  g.add(box(width, 2.1, 0.07, partMat, width / 2, 1.05, -0.02));
  const door = new THREE.Group();
  door.position.set(0.03, 0, 0.35);
  const leaf = box(width - 0.1, 1.9, 0.05, doorMat, (width - 0.1) / 2, 1.0, 0);
